import {CATEGORIES,sum,money,escapeHTML as e,grouped} from './core.mjs';
export const SCOPES={all:'All transactions',purchases:'Identified purchases',bankActivity:'Bank account activity',bankOut:'All bank money out',bankIn:'All bank money in',review:'Payments to review',property:'Property payments',investments:'Investments & saving',settlements:'Card bill payments',other:'Other bank payments'};
export function bankBucket(t){if(t.review)return 'review';if(CATEGORIES[t.category]?.expense)return 'purchases';return {'Property payments':'property','Investments & saving':'investments','Credit card payments':'settlements'}[t.category]||'other';}
export function inScope(t,scope){if(scope==='all')return true;if(scope==='purchases')return t.debit>0&&CATEGORIES[t.category]?.expense;if(scope==='review')return t.debit>0&&t.review;if(scope==='bankActivity')return t.account==='bank';if(scope==='bankIn')return t.account==='bank'&&t.credit>0;if(scope==='bankOut')return t.account==='bank'&&t.debit>0;return t.account==='bank'&&t.debit>0&&bankBucket(t)===scope;}
const COLORS={purchases:'#658354',property:'#324b3d',investments:'#6d9d9c',settlements:'#b39ac9',review:'#ca875b',other:'#adb69c'};
export function bankFlow(ts){const bank=ts.filter(t=>t.account==='bank'&&t.debit>0),total=sum(bank,'debit'),groups=grouped(bank,bankBucket);if(!total)return '<div class="empty">No bank payments in this period.</div>';return `<div class="flow-total"><span>Total money leaving your bank</span><strong>${money(total)}</strong></div><div class="flow-bar" aria-hidden="true">${groups.map(g=>`<span style="flex:${g.total};background:${COLORS[g.key]}"></span>`).join('')}</div><div class="flow-legend">${groups.map(g=>`<button data-scope="${g.key==='purchases'?'bankPurchases':g.key==='review'?'bankReview':g.key}"><span class="flow-dot" style="background:${COLORS[g.key]}"></span><span>${SCOPES[g.key]}<small>${(g.total/total*100).toFixed(1)}% of bank money out</small></span><strong>${money(g.total)} <span>↗</span></strong></button>`).join('')}</div><p class="panel-note">Bank accounts only. Card bill payments are separate from purchases so they aren’t counted twice. “Other” includes cash withdrawals and confirmed transfers.</p>`;}
export function spendingRing(ts){const groups=grouped(ts.filter(t=>inScope(t,'purchases')),'category'),total=sum(groups,'total');if(!total)return '<div class="empty">No identified purchases yet. Review payment categories or import a statement to see your spending mix.</div>';let offset=0;const circumference=2*Math.PI*78;return `<div class="spending-ring"><div class="ring-art"><svg viewBox="0 0 200 200" role="img" aria-label="Purchase category breakdown; use the category buttons to explore"><circle cx="100" cy="100" r="78" fill="none" stroke="#edf0e5" stroke-width="22"/>${groups.map(g=>{const length=g.total/total*circumference;const path=`<circle cx="100" cy="100" r="78" fill="none" stroke="${CATEGORIES[g.key].color}" stroke-width="22" stroke-dasharray="${length} ${circumference-length}" stroke-dashoffset="${-offset}" transform="rotate(-90 100 100)"><title>${e(g.key)}: ${money(g.total)}</title></circle>`;offset+=length;return path;}).join('')}</svg><div class="ring-label"><strong>${groups.length}</strong><span>spending categories</span></div></div><div class="ring-summary"><span class="eyebrow">BIGGEST CATEGORY</span><h3>${e(groups[0].key)}</h3><strong>${money(groups[0].total)}</strong><p>${(groups[0].total/total*100).toFixed(1)}% of identified purchases</p></div></div><div class="ring-legend">${groups.map(g=>`<button data-category="${e(g.key)}"><span class="flow-dot" style="background:${CATEGORIES[g.key].color}"></span><span>${e(g.key)}</span><strong>${money(g.total)}</strong><small>${(g.total/total*100).toFixed(0)}%</small><span aria-hidden="true">↗</span></button>`).join('')}</div>`;}
